// ❌ Memory leak: detached DOM node
let leakedElements = [];

function addItem() {
  let div = document.createElement("div");
  div.textContent = "Item";
  document.body.appendChild(div);
  leakedElements.push(div);  // reference kept!
}

function removeItem() {
  let div = document.body.firstChild;
  div.remove();  // removed from DOM
  // but leakedElements still holds the reference → leak!
}

// ✅ Fix: clear the reference
function removeItemFixed() {
  let div = document.body.firstChild;
  div.remove();
  leakedElements.shift();  // clear the reference → GC can collect

// ❌ Closure retains large object unnecessarily
function processData() {
  let hugeData = new Array(1000000).fill("data");
  let count = 0;

  // This closure retains hugeData even though it only uses count!
  return function increment() {
    count++;
    console.log(count);
  };
}

let increment = processData();
// hugeData is retained in closure scope → memory leak!

// ✅ Fix: extract only what's needed
function processDataFixed() {
  let hugeData = new Array(1000000).fill("data");
  let count = 0;
  hugeData = null;  // release the large array

  return function increment() {
    count++;
    console.log(count);
  };
}

